const input = $input.item.json;
const skills = input.skills || ["Coding", "Marketing"];
const budget = input.budget || 500;
const industry = input.industry || "Logistics";
const location = input.location || "Cairo";

// Inline execution or import of egypt-market-tool.js
let marketInsights = "";
try {
  const path = require('path');
  const egyptMarketTool = require(path.resolve(__dirname, '../scripts/egypt-market-tool.js'));
  marketInsights = egyptMarketTool.build(industry).text;
} catch (e) {
  // Self-contained fallback logic
  if (industry.toLowerCase().includes("logistics")) {
    marketInsights = "Egypt logistics indicators: Fuel subsidy cuts driving electric micro-mobility. Cairo/Giza density highly profitable.";
  } else {
    marketInsights = "Egypt general market indicators: 110M+ population, 72.2% internet penetration, instant cash payments preferred.";
  }
}

return {
  json: {
    prompt: `System: Generate a personalized business idea using skills ${skills.join(', ')}, budget ${budget}, in target location ${location}. Context: ${marketInsights}`,
    model: "gpt-4o-mini"
  }
};
